using HastaneRandevuSistemi.Models; using Microsoft.EntityFrameworkCore;
namespace HastaneRandevuSistemi.Data;
public class HospitalContext:DbContext{public HospitalContext(DbContextOptions<HospitalContext> o):base(o){} public DbSet<User> Users=>Set<User>();public DbSet<Doctor> Doctors=>Set<Doctor>();public DbSet<Patient> Patients=>Set<Patient>();public DbSet<Branch> Branches=>Set<Branch>();public DbSet<Appointment> Appointments=>Set<Appointment>();public DbSet<MedicalRecord> MedicalRecords=>Set<MedicalRecord>();protected override void OnModelCreating(ModelBuilder m){m.Entity<Doctor>().HasOne(x=>x.User).WithOne().HasForeignKey<Doctor>(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);m.Entity<Patient>().HasOne(x=>x.User).WithOne().HasForeignKey<Patient>(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);m.Entity<Doctor>().HasOne(x=>x.Branch).WithMany(x=>x.Doctors).HasForeignKey(x=>x.BranchId).OnDelete(DeleteBehavior.Restrict);m.Entity<Appointment>().HasOne(x=>x.Patient).WithMany(x=>x.Appointments).HasForeignKey(x=>x.PatientId).OnDelete(DeleteBehavior.Restrict);m.Entity<Appointment>().HasOne(x=>x.Doctor).WithMany(x=>x.Appointments).HasForeignKey(x=>x.DoctorId).OnDelete(DeleteBehavior.Restrict);m.Entity<MedicalRecord>().HasOne(x=>x.Patient).WithMany(x=>x.MedicalRecords).HasForeignKey(x=>x.PatientId).OnDelete(DeleteBehavior.Cascade);m.Entity<MedicalRecord>().HasOne(x=>x.Doctor).WithMany(x=>x.MedicalRecords).HasForeignKey(x=>x.DoctorId).OnDelete(DeleteBehavior.Restrict);}}
